CREATE TABLE IF NOT EXISTS workspace_conversations (id TEXT PRIMARY KEY, name TEXT, type TEXT NOT NULL DEFAULT 'DIRECT', created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY (created_by) REFERENCES app_users(id));
CREATE TABLE IF NOT EXISTS workspace_conversation_members (conversation_id TEXT NOT NULL, user_id TEXT NOT NULL, joined_at TEXT NOT NULL, PRIMARY KEY (conversation_id, user_id), FOREIGN KEY (conversation_id) REFERENCES workspace_conversations(id), FOREIGN KEY (user_id) REFERENCES app_users(id));
CREATE TABLE IF NOT EXISTS workspace_messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL, sender_id TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY (conversation_id) REFERENCES workspace_conversations(id), FOREIGN KEY (sender_id) REFERENCES app_users(id));
CREATE TABLE IF NOT EXISTS workspace_tasks (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', assigned_to TEXT NOT NULL, assigned_by TEXT NOT NULL, priority TEXT NOT NULL DEFAULT 'NORMAL', status TEXT NOT NULL DEFAULT 'PENDING', due_date TEXT, linked_entity_type TEXT, linked_entity_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY (assigned_to) REFERENCES app_users(id), FOREIGN KEY (assigned_by) REFERENCES app_users(id));
CREATE TABLE IF NOT EXISTS workspace_requests (id TEXT PRIMARY KEY, request_type TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', requested_by TEXT NOT NULL, assigned_to TEXT NOT NULL, priority TEXT NOT NULL DEFAULT 'NORMAL', status TEXT NOT NULL DEFAULT 'PENDING', due_date TEXT, linked_entity_type TEXT, linked_entity_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY (requested_by) REFERENCES app_users(id), FOREIGN KEY (assigned_to) REFERENCES app_users(id));
CREATE TABLE IF NOT EXISTS workspace_activity (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, event_type TEXT NOT NULL, description TEXT NOT NULL, reference_type TEXT, reference_id TEXT, created_at TEXT NOT NULL, FOREIGN KEY (actor_id) REFERENCES app_users(id));
CREATE INDEX IF NOT EXISTS idx_workspace_members_user ON workspace_conversation_members(user_id);
CREATE INDEX IF NOT EXISTS idx_workspace_messages_conversation ON workspace_messages(conversation_id, created_at);
CREATE INDEX IF NOT EXISTS idx_workspace_tasks_assigned ON workspace_tasks(assigned_to, status);
CREATE INDEX IF NOT EXISTS idx_workspace_requests_assigned ON workspace_requests(assigned_to, status);
CREATE INDEX IF NOT EXISTS idx_workspace_activity_created ON workspace_activity(created_at);
UPDATE app_users SET permissions_json = CASE WHEN permissions_json = '[]' THEN '["workspace"]' WHEN instr(permissions_json, '"workspace"') = 0 THEN replace(permissions_json, ']', ',"workspace"]') ELSE permissions_json END WHERE access_status = 'APPROVED' AND role <> 'ADMIN';